import { motion } from "framer-motion";

const images = [
  {
    src: "https://images.unsplash.com/photo-1576678927484-cc907957088c?auto=format&fit=crop&w=1200&q=80",
    caption: "Clean interiors designed for focused training",
  },
  {
    src: "https://images.unsplash.com/photo-1584467735871-bc8f6f6b4e63?auto=format&fit=crop&w=800&q=80",
    caption: "Professional-grade equipment for structured workouts",
  },
  {
    src: "https://images.unsplash.com/photo-1599058917212-d750089bc07e?auto=format&fit=crop&w=800&q=80",
    caption: "Spacious layouts supporting safe and efficient movement",
  },
  {
    src: "https://images.unsplash.com/photo-1558611848-73f7eb4001a1?auto=format&fit=crop&w=600&q=80",
    caption: "Well-maintained spaces promoting comfort and consistency",
  },
];

export default function TrainingEnvironment() {
  return (
    <section className="bg-black text-white py-28 px-6 overflow-hidden">
      <div className="max-w-7xl mx-auto grid md:grid-cols-2 gap-20 items-center">

        {/* LEFT CONTENT */}
        <motion.div
          initial={{ opacity: 0, x: -40 }}
          whileInView={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
          viewport={{ once: true }}
        >
          <h2 className="text-4xl md:text-5xl font-bold leading-tight">
            Training <span className="text-red-600">Environment</span>
          </h2>

          <p className="mt-6 text-gray-300 leading-relaxed">
            Bodyzeal Fitworks gyms are designed to support focused training with
            disciplined layouts, clean workout spaces, and professional-grade
            equipment. Every environment is built to encourage consistency,
            safety, and long-term progress.
          </p>

          <div className="mt-10 space-y-4">
            {images.map((item, i) => (
              <div key={i} className="flex items-start gap-3 text-sm text-gray-400">
                <span className="text-red-600 font-bold">—</span>
                <span>{item.caption}</span>
              </div>
            ))}
          </div>
        </motion.div>

       {/* RIGHT IMAGES */}
<div className="relative h-[520px] w-full">

  {/* Main Image */}
  <motion.img
    src={images[0].src}
    alt="Gym Interior"
    className="absolute top-0 left-0 w-full h-64 object-cover rounded-2xl shadow-2xl"
    initial={{ opacity: 0, y: 40 }}
    whileInView={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.8 }}
    viewport={{ once: true }}
  />

  {/* Center Image */}
  <motion.img
    src={images[1].src}
    alt="Equipment"
    className="absolute top-44 left-1/2 -translate-x-1/2 w-64 h-52 object-cover rounded-xl shadow-xl border border-white/10 z-20"
    animate={{ y: [0, -12, 0] }}
    transition={{ duration: 6, repeat: Infinity }}
  />

  {/* Bottom Left */}
  <motion.img
    src={images[2].src}
    alt="Workout Floor"
    className="absolute bottom-0 left-0 w-56 h-44 object-cover rounded-xl shadow-lg border border-white/10"
    animate={{ y: [0, 10, 0] }}
    transition={{ duration: 7, repeat: Infinity }}
  />

  {/* Bottom Right */}
  <motion.img
    src={images[3].src}
    alt="Clean Gym"
    className="absolute bottom-6 right-0 w-48 h-40 object-cover rounded-xl shadow-lg border border-white/10"
    animate={{ y: [0, -8, 0] }}
    transition={{ duration: 5, repeat: Infinity }}
  />

</div>

      </div>
    </section>
  );
}
